*{box-sizing:border-box}
 :root{--ink:#f4f4ed;--muted:#a9b3b0;--faint:#7a8987;--panel:rgba(15,26,30,.82);--line:rgba(226,238,231,.12);--mint:#b6dfc7;--gold:#e7c488}
 html,body,#game{margin:0;width:100%;height:100%;overflow:hidden}
 body{background:#a6b8ad;color:var(--ink);font-family:'DM Sans',sans-serif}
 button{font:inherit;color:inherit}
 #scene{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}
.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(8,17,21,.35),transparent 30%,transparent 70%,rgba(8,17,21,.3)),linear-gradient(0deg,rgba(8,17,21,.38),transparent 25%,transparent 72%,rgba(8,17,21,.22))}
.topbar{position:absolute;left:0;right:0;top:0;height:76px;padding:0 31px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.09);background:linear-gradient(180deg,rgba(11,19,23,.82),rgba(11,19,23,.26));z-index:3}
.brand{display:flex;align-items:center;gap:11px}
.brand-mark{width:33px;height:33px;border:1px solid rgba(182,223,199,.65);border-radius:50%;display:grid;place-items:center;font:700 18px Manrope;color:var(--mint)}
.brand strong{display:block;font:800 12px Manrope;letter-spacing:1.55px}
.brand strong i{font-style:normal;color:var(--mint)}
.brand small{display:block;margin-top:3px;color:#99aaa5;font:500 8px 'DM Mono';letter-spacing:1.5px}
.world-label{display:flex;align-items:center;gap:8px;color:#c4cfca;font:10px 'DM Mono';letter-spacing:1.15px}
.live-dot{height:6px;width:6px;border-radius:50%;background:#a8dbb5;box-shadow:0 0 11px #8bd19e}
.icon-button{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.15);border-radius:5px;padding:9px 13px;color:var(--mint);font-size:15px;cursor:pointer}
.icon-button span{font:10px 'DM Mono';letter-spacing:1px;color:#e5ebe7;margin-left:4px}
.left-rail,.right-rail{position:absolute;top:96px;width:242px;display:flex;flex-direction:column;gap:9px;z-index:2}
.left-rail{left:23px}
.right-rail{right:23px}
.rail-card,.clock-card,.world-card,.controls-card{background:var(--panel);border:1px solid var(--line);border-radius:7px;backdrop-filter:blur(13px);box-shadow:0 10px 36px rgba(0,0,0,.13)}
.profile-card{padding:14px;display:flex;align-items:center;gap:11px}
.avatar{height:37px;width:37px;border-radius:50%;background:linear-gradient(140deg,#d9b892,#6d8780);display:grid;place-items:center;color:#142322;font:800 17px Manrope}
.eyebrow,.section-title{font:9px 'DM Mono';letter-spacing:1.15px;color:#9daaa6}
.profile-copy strong{display:block;font:700 11px Manrope;letter-spacing:.3px;margin:3px 0}
.profile-copy small,.wallet-card>small{font-size:10px;color:#aab5b0}
.needs-card{padding:14px 14px 13px}
.section-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}
.section-title>span{font-size:8px;color:var(--mint)}
.need-row{display:grid;grid-template-columns:52px 1fr 22px;gap:8px;align-items:center;margin:10px 0;font-size:10px;color:#c4cfca}
.need-row b{font:10px 'DM Mono';text-align:right;color:#e0e5df}
.meter{height:4px;background:rgba(255,255,255,.1);border-radius:4px;overflow:hidden}
.meter i{height:100%;width:50%;display:block;border-radius:4px;transition:width .5s}
.energy{background:#9cd5ae}
.hunger{background:#e5c181}
.social{background:#a8bbdc}
.stress{background:#da9887}
.wallet-card{padding:13px 15px}
.wallet-card .section-title{margin-bottom:5px}
.money{font:500 26px 'DM Sans';letter-spacing:-.7px}
.money span{color:var(--mint);font-size:15px;margin-right:2px}
.wallet-card>small{font-size:9px}
.journal-card{padding:13px 14px;min-height:145px}
.journal-card .section-title{margin-bottom:7px}
.log-count{font:9px 'DM Mono';color:#92a49d!important}
.log-list{display:flex;flex-direction:column;gap:0}
.log-item{padding:8px 0;border-top:1px solid rgba(255,255,255,.07);display:grid;grid-template-columns:35px 1fr;gap:6px;font-size:9px;color:#bdc7c1;line-height:1.45}
.log-item time{font:8px 'DM Mono';color:#8faaa0}
.clock-card{padding:15px}
.clock-card .eyebrow{font-size:8px}
.clock-card>strong{display:block;font:600 36px Manrope;letter-spacing:-1.5px;margin:3px 0 4px}
.weather{display:flex;align-items:center;gap:8px;font:9px 'DM Mono';letter-spacing:.65px;color:#c2cdc7}
.weather span:first-child{font-size:16px;color:#edca85}
.dayline{height:2px;background:rgba(255,255,255,.12);margin-top:13px}
.dayline i{height:2px;width:35%;display:block;background:var(--mint)}
.world-card{padding:14px}
.world-card .section-title{margin-bottom:8px}
.signal{font-size:8px;color:#a7d2b2!important}
.world-card p{color:#b4c0ba;font-size:10px;line-height:1.5;margin:0 0 11px}
.statline{display:flex;justify-content:space-between;padding-top:8px;margin-top:8px;border-top:1px solid rgba(255,255,255,.07);font-size:9px;color:#aab7b0}
.statline b{font-weight:500;color:#e1e6e1}
.controls-card{padding:13px 14px}
.controls-card .section-title{margin-bottom:9px}
.controls-card>div:not(.section-title){height:25px;display:flex;align-items:center;gap:4px;font-size:9px;color:#bac5bf}
.controls-card kbd,.interaction-hint kbd{font:8px 'DM Mono';color:#e0e9e2;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.07);border-radius:3px;padding:4px 5px;min-width:19px;text-align:center}
.controls-card span{margin-left:5px}
.crosshair{position:absolute;top:50%;left:50%;width:16px;height:16px;transform:translate(-50%,-50%);opacity:.7;pointer-events:none}
.crosshair i{position:absolute;background:rgba(240,245,236,.85)}
.crosshair i:first-child{height:1px;width:13px;left:1px;top:7px}
.crosshair i:last-child{height:13px;width:1px;left:7px;top:1px}
.interaction-hint{position:absolute;left:50%;top:calc(50% + 24px);transform:translateX(-50%);display:none;align-items:center;gap:7px;padding:6px 9px;border-radius:4px;background:rgba(13,23,26,.76);font:8px 'DM Mono';letter-spacing:.7px;color:#dae4dd}
.interaction-hint.visible{display:flex}
.location-toast{position:absolute;bottom:30px;left:25px;display:flex;align-items:center;gap:10px;background:rgba(15,26,30,.69);border:1px solid var(--line);padding:10px 13px;border-radius:5px;backdrop-filter:blur(8px)}
.location-toast>span{font-size:18px;color:var(--mint)}
.location-toast small{display:block;font:8px 'DM Mono';letter-spacing:.9px;color:#9aaba3}
.location-toast strong{font:600 11px Manrope}
.bottom-center{position:absolute;bottom:25px;left:50%;transform:translateX(-50%);width:min(510px,calc(100% - 540px));min-width:380px;display:flex;flex-direction:column;gap:8px}
.objective{height:64px;border:1px solid rgba(255,255,255,.16);background:rgba(15,26,30,.83);backdrop-filter:blur(14px);border-radius:6px;display:flex;align-items:center;padding:0 13px;gap:11px;box-shadow:0 12px 30px rgba(0,0,0,.16)}
.objective-mark{width:27px;height:27px;border-radius:50%;border:1px solid rgba(182,223,199,.48);display:grid;place-items:center;color:var(--mint)}
.objective>div{flex:1}
.objective small{display:block;font:8px 'DM Mono';letter-spacing:1px;color:#9dada5}
.objective strong{display:block;margin-top:4px;font:500 11px Manrope;color:#f0f1eb}
.objective button{border:0;border-left:1px solid rgba(255,255,255,.15);padding:8px 0 8px 13px;background:none;color:#b8c5bd;font:8px 'DM Mono';letter-spacing:.7px;cursor:pointer}
.objective button span{font-size:13px;color:var(--mint);margin-left:5px}
.interaction-panel{display:none}
.toast{position:absolute;top:85px;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:rgba(17,30,31,.94);border:1px solid rgba(182,223,199,.24);padding:10px 17px;border-radius:5px;color:#e8eee8;font-size:11px;pointer-events:none}
.toast.show{opacity:1;transform:translate(-50%,0)}
.start-screen{position:absolute;inset:0;z-index:5;display:flex;align-items:center;background:linear-gradient(90deg,rgba(13,24,26,.93) 0%,rgba(13,24,26,.84) 38%,rgba(13,24,26,.12) 76%,rgba(13,24,26,.05) 100%);transition:opacity .7s,visibility .7s}
