input.content:
/* Touch-first layout and controls for phones and tablets. */
.mobile-clock,.mobile-status,.touch-controls{display:none}
#scene{touch-action:none}
button{touch-action:manipulation}
@media(max-width:700px){
  html,body,#game{height:100%;height:100dvh;min-height:100%;}
  .topbar{height:calc(54px + env(safe-area-inset-top));padding:env(safe-area-inset-top) 9px 0;gap:6px;justify-content:space-between;}
  .brand{gap:7px;min-width:0}.brand-mark{width:29px;height:29px;font-size:15px}.brand strong{font-size:10px;letter-spacing:1px}.brand small{font-size:7px;letter-spacing:.8px}
  .world-label{display:none}
  .mobile-clock{display:flex;flex-direction:column;align-items:center;gap:1px;margin-left:auto;min-width:46px;color:#f0f3ed;font:600 12px 'DM Mono';}
  .mobile-clock small{font:8px 'DM Mono';color:#b4c5ba}
  .mobile-status{display:inline-flex}
  .icon-button{width:35px;height:35px;padding:0;display:grid;place-items:center;font-size:15px;border-radius:6px;flex:none}
  .icon-button span{display:none}
